    state.customerId = ev.payload.customerId;
    state.currency = ev.payload.currency;
    state.phase = 'intake';
    const placed = { ...ev.payload, orderId, placedAt: ev.at };
    const r = ctx.call('intake', orderId, { op: 'placed', order: placed });
