// TEMPORARY PROBE: instances() shape for an order with an open instance (the order's own instance is the subject).
export function tick(input, ctx) {
  const n = Number(input.instance.slice(2)) - 1;
  const ev = input.events[0];
  const subj = ev?.payload?.orderId ?? ev?.payload?.orderRef ?? 'ORD-1235-0002';
  const list = ctx.instances({ subject: String(subj).trim().toUpperCase() });
  const ord = ctx.query('orders.orders', { where: { orderId: String(subj).trim().toUpperCase() }, limit: 1 });
  throw new Error(`I${n} list=` + JSON.stringify(list).slice(0, 110) + ' rec=' + JSON.stringify(ord).slice(0, 60));
}

