1	// Parent orchestrator: routing and the order of the phases (DECOMPOSITION.md §3). It emits no effects itself: every
2	// system is reached through a module. Owns SPEC-E §1 (routing, subject, delivery order), §3.2, §3.5, §4 preamble,
3	// R7.1 (no close while a module is busy), and the phase order of S5, S8-S13, S15.
4	//
5	// Parent state (JSON; the whole carry stays under 64 KB):
6	//   { phase: 'new'|'intake'|'fraud'|'waiting'|'processing'|'ended', orderId, placedAt, customerId, currency, edition,
7	//     fulfilments: [{ fulfilmentId, location, available, items, amountMinor }], readyAt, readyDone,
8	//     started: { [fid]: true }, sagas: { [fid]: { end, reported } }, busy: { [module]: boolean }, held: [action] }
9	
10	const FULFILMENT_ENDS = ['completed', 'failed'];
11	
12	export function tick(input, ctx) {
13	  const state = input.state ?? newState();
14	  const events = input.events ?? [];
15	  let first = true;
16	  if (state.phase === 'new') {
17	    const r = firstTick(events[0], state, input, ctx);
18	    if (r.merge) return { decisions: { subject: r.subject }, state, merge: { into: r.merge } };
19	    if (r.close) return { decisions: { subject: r.subject ?? null }, state, close: true };
20	    first = false;
21	  }
22	  for (const ev of first ? events : events.slice(1)) handleEvent(ev, state, input, ctx);
23	  if (state.phase === 'processing') endOfTick(state, input, ctx);
24	  const out = { decisions: { subject: state.orderId ?? null }, state };
25	  if (shouldClose(state)) out.close = true;
26	  return out;
27	}
28	
29	function newState() {
30	  return { phase: 'new', orderId: null, placedAt: null, customerId: null, currency: null, edition: null, fulfilments: [],
31	    readyAt: null, readyDone: false, started: {}, sagas: {}, busy: {}, held: [] };
32	}
33	
34	// ---------------------------------------------------------------------------------------------------------------------
35	// The first tick of an instance started by a message (§1 Routing, §3.2, §3.3, §3.5)
36	
37	function firstTick(ev, state, input, ctx) {
38	  if (!ev) return { close: true, subject: null };
39	  if (ev.type === 'migration') return resumeMigration(ev, state, input, ctx);
40	  if (ev.type === 'order.placed') {
41	    const orderId = normalise(ev.payload.orderId, ctx);
42	    const open = openElsewhere(orderId, input, ctx);
43	    if (open) return { merge: open, subject: orderId };
44	    if (recordedOrder(orderId, ctx)) return { close: true, subject: orderId };     // R1.4: a recorded duplicate
45	    state.orderId = orderId;
46	    state.placedAt = ev.at;                                                        // §3.1: placedAt is the event's time
47	    state.customerId = ev.payload.customerId;
48	    state.currency = ev.payload.currency;
49	    state.phase = 'intake';
50	    const r = ctx.call('intake', orderId, { op: 'placed', order: placedOrder(ev, orderId) });
51	    absorbIntake(r, state, ctx);
52	    return { subject: orderId };
53	  }
54	  if (ev.type === 'customer.action') {
55	    const orderId = normalise(ev.payload.orderRef, ctx);
56	    if (!orderId) return { close: true, subject: null };                          // §3.2: names no order: nothing
57	    const open = openElsewhere(orderId, input, ctx);
58	    if (open) return { merge: open, subject: orderId };
59	    return { close: true, subject: orderId };                                     // ended or unknown: changes nothing
60	  }
61	  if (ev.type === 'carrier.status') {
62	    const orderId = orderOfFulfilment(ev.payload.fulfilmentRef, ctx);
63	    if (orderId) {
64	      const open = openElsewhere(orderId, input, ctx);
65	      if (open) return { merge: open, subject: orderId };
66	    }
67	    return { close: true, subject: orderId };                                    // §3.3: changes nothing
68	  }
69	  return { close: true, subject: null };
70	}
71	
72	function resumeMigration(ev, state, input, ctx) {
73	  // §3.5: continue from where the order stands. The records say what exists; the messages already received are
74	  // replayed through the same handlers (they are idempotent), and the rules continue unchanged.
75	  const rec = ev.payload.records ?? {};
76	  const row = (rec['orders.orders'] ?? [])[0];
77	  if (!row) return { close: true, subject: null };
78	  const orderId = normalise(row.orderId, ctx);
79	  const rows = rec['orders.fulfilments'] ?? [];
80	  state.orderId = orderId;
81	  state.customerId = row.customerId;
82	  state.currency = row.currency;
83	  state.placedAt = row.placedAt;
84	  state.edition = ctx.call('intake', orderId, { op: 'resume', records: rec }).edition;
85	  state.fulfilments = rows.map(f => ({ fulfilmentId: f.fulfilmentId, location: f.location ?? null, available: (f.location ?? null) !== null,
86	    items: mergeItems(f.items ?? []), amountMinor: f.amountMinor ?? 0 }));
87	  ctx.call('statuses', orderId, { op: 'resume', orderId, records: { order: row.status, fulfilments: rows.map(f => ({ fulfilmentId: f.fulfilmentId, status: f.status })) } });
88	  ctx.call('notices', orderId, { op: 'resume', customerId: row.customerId, sent: (rec['notify.notifications'] ?? []).map(n => `${n.template}.${n.about}`) });
89	  const pending = row.status === 'pending';
90	  if (pending) {
91	    // Still before clearing: the fraud check is read again; a review task is asked again if the verdict needs one.
92	    ctx.call('fraud', orderId, { op: 'start', orderId, placedAt: row.placedAt, edition: state.edition });
93	    state.phase = 'fraud';
94	  } else {
95	    ctx.call('fraud', orderId, { op: 'resume', records: { state: 'cleared', placedAt: row.placedAt, edition: state.edition, at: row.placedAt } });
96	    state.phase = row.status === 'processing' ? 'processing' : row.status === 'customerActionRequired' ? 'waiting' : 'ended';
97	  }
98	  const ca = ctx.call('customer-action', orderId, { op: 'resume', placedAt: row.placedAt, edition: state.edition, records: rec });
99	  state.busy.ca = ca.busy;
100	  if (state.phase === 'processing') {
101	    state.readyAt = row.placedAt;
102	    state.readyDone = true;
103	    ctx.call('order-progress', orderId, { op: 'resume', records: { state: 'processing' } });
104	    for (const f of state.fulfilments) {
105	      if (!f.available) continue;
106	      state.started[f.fulfilmentId] = true;
107	      const out = ctx.call('fulfilment', f.fulfilmentId, { op: 'resume', records: fulfilmentRecord(f, state, rec, rows) });
108	      onFulfilment(f.fulfilmentId, out, state, ctx);
109	    }
110	  }
111	  for (const e of ev.payload.events ?? []) if (e.type !== 'order.placed') handleEvent(e, state, input, ctx);
112	  return { subject: orderId };
113	}
114	
115	// The fulfilment's saga state, read back from its records (reservations, charge, shipment and status rows).
116	function fulfilmentRecord(f, state, rec, rows) {
117	  const fid = f.fulfilmentId;
118	  const status = (rows.find(r => r.fulfilmentId === fid) ?? {}).status ?? 'pending';
119	  const reserved = (rec['inventory.reservations'] ?? []).filter(x => x.fulfilmentId === fid && x.status === 'active').map(x => x.sku);
120	  const charged = (rec['billing.charges'] ?? []).some(x => x.fulfilmentId === fid);
